<?php
/** Verify the quote generated by the checkout hook without contacting WhatsApp. */
define( 'ABSPATH', __DIR__ );
function add_action( $hook, $callback ) { $GLOBALS['hooks'][ $hook ] = $callback; }
function wp_strip_all_tags( $text ) { return strip_tags( $text ); }
function number_format_i18n( $number ) { return number_format( $number, 0, ',', '.' ); }
function esc_url( $url ) { return htmlspecialchars( $url, ENT_QUOTES ); }
function WC() { return $GLOBALS['wc']; }
require __DIR__ . '/../../wordpress/grafik-publicidad/inc/checkout-whatsapp.php';

$cart = new class {
	public array $items = array();
	function is_empty() { return ! $this->items; }
	function get_cart() { return $this->items; }
	function get_total() { return '<bdi>&#36;26.000</bdi>'; }
};
$GLOBALS['wc'] = (object) array( 'cart' => $cart );
function checkout_quote() {
	ob_start();
	$GLOBALS['hooks']['woocommerce_review_order_after_submit']();
	return ob_get_clean();
}
if ( '' !== checkout_quote() ) { throw new Exception( 'Empty cart shows quote' ); }
$cart->items = array(
	array( 'quantity' => 2, 'grafik_units' => 200, 'grafik_color' => 'Azul', 'data' => new class { function get_name() { return 'Pulseras Tyvek'; } } ),
	array( 'quantity' => 10, 'data' => new class { function get_name() { return 'Chapita alfiler'; } } ),
);
$html = checkout_quote();
preg_match( '/href="([^"]+)"/', $html, $match );
$url = parse_url( html_entity_decode( $match[1] ) );
parse_str( $url['query'], $query );
if ( 'https' !== $url['scheme'] || 'wa.me' !== $url['host'] || '/56985074469' !== $url['path'] ) { throw new Exception( 'Wrong recipient' ); }
foreach ( array( 'Pulseras Tyvek × 200 unidades · Azul', 'Chapita alfiler × 10 unidades', 'Total del carrito: $26.000' ) as $expected ) {
	if ( ! str_contains( $query['text'], $expected ) ) { throw new Exception( $expected ); }
}
echo "PASS: checkout quote recipient, product quantities, total and empty cart.\n";
